import{_ as l,a0 as d,w as a,s as p,ao as c,I as s,x as o,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"使用開源工具 nccm 管理 SSH 連接 | LCTT x X-CMD","titleTemplate":false,"description":"使用開源工具 nccm 管理 SSH 連接 | LCTT (202009) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用開源工具 nccm 管理 SSH 連接 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用開源工具 nccm 管理 SSH 連接 | LCTT (202009) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202009/20200909 Manage your SSH connections with this open source tool","title":"使用開源工具 nccm 管理 SSH 連接","tag":"202009","desc":""},"relativePath":"202009/20200909 Manage your SSH connections with this open source tool.md","filePath":"[post].md"}'),r={name:"202009/20200909 Manage your SSH connections with this open source tool.md"};function m(h,e,u,g,k,b){const n=d("Link");return a(),p("div",null,[e[25]||(e[25]=c('<h1 id="使用開源工具-nccm-管理-ssh-連接" tabindex="-1">使用開源工具 nccm 管理 SSH 連接 <a class="header-anchor" href="#使用開源工具-nccm-管理-ssh-連接" aria-label="Permalink to “使用開源工具 nccm 管理 SSH 連接”">​</a></h1><blockquote><p>使用 nccm 讓你的終端連接 SSH 會話更快、更穩、更輕鬆。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202009/19/233942j6ne6wllnlbnjd36.jpg" alt=""></p><p>OpenSSH 很常用，但沒有一個知名的連接管理器，因此我開發了 ncurses SSH 連接管理器（<code>nccm</code>）來填補這個重要的空白。 <code>nccm</code> 是一個簡單的 SSH 連接管理器，具有非常便於移植的終端界面（就如項目名稱所示，使用 ncurses 編寫）。最重要的是，它使用起來非常簡單。有了 <code>nccm</code>，你可以花費最少的精力和最少的按鍵連接到你選擇的 SSH 會話。</p><h3 id="安裝-nccm" tabindex="-1">安裝 nccm <a class="header-anchor" href="#安裝-nccm" aria-label="Permalink to “安裝 nccm”">​</a></h3>',5)),s("p",null,[e[1]||(e[1]=o("最快的方式是從它的 ",-1)),i(n,{href:"https://github.com/flyingrhinonz/nccm"},{default:t(()=>[...e[0]||(e[0]=[o("Git 倉庫",-1)])]),_:1}),e[2]||(e[2]=o("克隆該項目：",-1))]),e[26]||(e[26]=c('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone https://github.com/flyingrhinonz/nccm nccm.git</span></span></code></pre></div><p>在 <code>nccm.git/nccm</code> 的文件夾中有兩個文件：<code>nccm</code> 自身和 <code>nccm.yml</code> 配置文件。</p><p>首先將 <code>nccm</code> 腳本複製到系統目錄 <code>/usr/local/bin/</code> 中並添加執行權限，也可以通過使用<code>install</code> 命令來完成操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo install -m755 nccm –target-directory /usr/local/bin</span></span></code></pre></div><p>文件 <code>nccm.yml</code> 可以拷貝到以下任意一個位置，默認從找到的第一個位置獲取配置:</p><ul><li><code>~/.config/nccm/nccm.yml</code></li><li><code>~/.nccm.yml</code></li><li><code>~/nccm.yml</code></li><li><code>/etc/nccm.yml</code></li></ul><p><code>nccm</code> 需要在 Python 3 的環境中運行，這在大部分的 Linux 環境是沒問題的。大多數 Python 庫的依賴包已經作為 Python 3 的一部分存在，但是，有一些 YAML 的依賴包和實用程序是你必須安裝的。</p><p>如果你沒有安裝 <code>pip</code>，你可以使用包管理器來安裝它。在安裝的同時，也請安裝 <code>yamllint</code> 應用程序來幫助你驗證 <code>nccm.yml</code> 文件。</p><p>在 Debian 或類似系統使用 <code>apt</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install python3-pip yamllint</span></span></code></pre></div><p>在 Fedora 或者類似系統使用 <code>dnf</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install python3-pip yamllint</span></span></code></pre></div><p><code>PyYAML</code> 也是必須安裝的，可以通過使用 <code>pip</code> 來安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pip3 install --user PyYAML</span></span></code></pre></div><h3 id="使用-nccm" tabindex="-1">使用 nccm <a class="header-anchor" href="#使用-nccm" aria-label="Permalink to “使用 nccm”">​</a></h3><p>開始之前，需要修改 <code>nccm.yml</code> 文件來添加 SSH 連接配置，可以參照示例文件格式化 YAML 文件。仿照示例文件在開頭添加連接名稱，配置項使用兩個空格縮進。不要忘了冒號（<code>:</code>），這是 YAML 的語言的格式。</p><p>不要擔心你的 SSH 會話信息以何順序排列，因為 <code>nccm</code> 在程序內提供了排序的方式。</p><p>如果修改完成，可以使用 <code>yamllint</code> 來校驗配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yamllint ~/.config/nccm/nccm.yml</span></span></code></pre></div><p>如果沒有錯誤信息返回，説明文件的內容格式是正確的，可以進行下面的步驟。</p>',20)),s("p",null,[e[4]||(e[4]=o("如果 ",-1)),e[5]||(e[5]=s("code",null,"nccm",-1)),e[6]||(e[6]=o(" 可以",-1)),i(n,{href:"https://opensource.com/article/17/6/set-path-linux"},{default:t(()=>[...e[3]||(e[3]=[o("從你的路徑",-1)])]),_:1}),e[7]||(e[7]=o("中找到並且可以執行，那麼輸入 ",-1)),e[8]||(e[8]=s("code",null,"nccm",-1)),e[9]||(e[9]=o(" 就可以啓動 TUI（文本用户界面）了。如果你看到 Python 3 拋出的異常，請檢查依賴包是否正確安裝，任何異常都應該提到缺少的依賴包。",-1))]),e[27]||(e[27]=c('<p>只要你沒有在 YAML 配置文件中更改 <code>ncm_config_control</code> 模式，那麼你可以使用以下的鍵盤按鍵來控制：</p><ul><li><code>Up</code>/<code>Down</code> 方向鍵 - 移動光標</li><li><code>Home</code>/<code>End</code> - 跳轉到文件開始和結尾</li><li><code>PgUp</code>/<code>PgDn</code> - 以頁為單位查看</li><li><code>Left</code>/<code>Right</code> 方向鍵 - 水平滾動</li><li><code>TAB</code> - 在文本框之間移動</li><li>回車 - 連接選中的 SSH 會話</li><li><code>Ctrl-h</code> - 顯示幫助菜單</li><li><code>Ctrl-q</code>/<code>Ctrl-c</code> - 退出</li><li><code>F1</code>-<code>F5</code> 或 <code>!</code> <code>@</code> <code>#</code> <code>$</code> <code>%</code> - 按 1-5 列排序</li></ul><p>使用 <code>F1</code> 到 <code>F5</code> 來按 1-5 列排序，如果你的設備佔用了這些 <code>F1</code> - <code>F5</code> 鍵，你可以使用<code>!</code> <code>@</code> <code>#</code> <code>$</code> <code>%</code> 來替代。默認界面顯示 4 列內容，但我們將用户名和服務器地址作為單獨的列來排序，這樣我們就有了 5 個排序方式。你也可以通過再次按下排序的按鍵來逆轉排序。在選中的行上按回車可以建立會話。</p><p><img src="https://opensource.com/sites/default/files/uploads/nccm_screenshot.png" alt="nccm screenshot terminal view" title="nccm screenshot terminal view"></p><p>在 <code>Filter</code> 文本框中輸入過濾內容，會用輸入的內容以“與”的關係來過濾輸出內容。這是不區分大小寫的，而條目間用空白分隔。在 <code>Conn</code> 部分也是如此，但在這裏按回車鍵可以連接到那個特定的條目編號。</p><p>這個工具還有許多功能需要你去發掘，比如專注模式，這些部分留下等待你去探索，也可以查看項目主頁或者內置的幫助文檔查看更多細節內容。</p><p>項目的 YAML 配置文件的文檔是完善的，所以你可以查閲修改使 <code>nccm</code> 使用起來更加順手。<code>nccm</code> 項目是非常希望得到你的反饋的，所以你可以復刻該項目然後添加更多新功能，歡迎大家提出拉取請求。</p><h3 id="使用-nccm-來放鬆連接-ssh-的壓力" tabindex="-1">使用 nccm 來放鬆連接 SSH 的壓力 <a class="header-anchor" href="#使用-nccm-來放鬆連接-ssh-的壓力" aria-label="Permalink to “使用 nccm 來放鬆連接 SSH 的壓力”">​</a></h3><p>像我一樣，我希望這個工具可以對你有用，感謝能夠為開源工作增加自己的貢獻，請接受 <code>nccm</code> 作為我對開源項目自由、高效工作所做的貢獻。</p><hr>',10)),s("p",null,[e[11]||(e[11]=o("via: ",-1)),i(n,{href:"https://opensource.com/article/20/9/ssh-connection-manager"},{default:t(()=>[...e[10]||(e[10]=[o("https://opensource.com/article/20/9/ssh-connection-manager",-1)])]),_:1})]),s("p",null,[e[16]||(e[16]=o("作者：",-1)),i(n,{href:"https://opensource.com/users/flyingrhino"},{default:t(()=>[...e[12]||(e[12]=[o("Kenneth Aaron",-1)])]),_:1}),e[17]||(e[17]=o(" 選題：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[13]||(e[13]=[o("lujun9972",-1)])]),_:1}),e[18]||(e[18]=o(" 譯者：",-1)),i(n,{href:"https://github.com/hom"},{default:t(()=>[...e[14]||(e[14]=[o("hom",-1)])]),_:1}),e[19]||(e[19]=o(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:t(()=>[...e[15]||(e[15]=[o("wxy",-1)])]),_:1})]),s("p",null,[e[22]||(e[22]=o("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[20]||(e[20]=[o("LCTT",-1)])]),_:1}),e[23]||(e[23]=o(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:t(()=>[...e[21]||(e[21]=[o("Linux中國",-1)])]),_:1}),e[24]||(e[24]=o(" 榮譽推出",-1))])])}const T=l(r,[["render",m]]);export{y as __pageData,T as default};
